"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["9586"],{13809(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.grupo_area_enem_snapshot.caractere_invalido","status":422,"titulo":"Grupo de \xe1rea do ENEM cont\xe9m caractere nulo, de controle, de formata\xe7\xe3o ou que n\xe3o \xe9 texto"},"descricao":{"codigo":"uniplus.selecao.grupo_area_enem_snapshot.caractere_invalido","requisitos":[],"oQueAconteceu":["O c\xf3digo ou o r\xf3tulo do grupo de \xe1rea do ENEM cont\xe9m o caractere nulo (U+0000), um caractere de controle ou\\nde formata\xe7\xe3o, ou outro caractere que n\xe3o \xe9 texto, como um surrogate sem par. O texto congelado entra aparado e\\nnormalizado, e esses caracteres s\xe3o recusados porque n\xe3o fazem parte de um c\xf3digo nem de um r\xf3tulo leg\xedveis; deix\xe1-los passar\\nfaria a falha aparecer s\xf3 depois, na grava\xe7\xe3o ou na publica\xe7\xe3o.","Cada oferta da distribui\xe7\xe3o de vagas e cada grupo do quadro de pesos por \xe1rea da classifica\xe7\xe3o\\nguardam uma c\xf3pia do grupo de \xe1rea do ENEM do curso, com c\xf3digo e r\xf3tulo, congelada com o processo.\\nO c\xf3digo \xe9 a identidade do grupo (\xe9 por ele que o processo casa a oferta com a linha de Pesos por\\n\xc1rea), e o r\xf3tulo \xe9 o que o edital publicado mostra. Editar o curso depois n\xe3o alcan\xe7a o processo;\\nquem quiser o grupo novo redefine a distribui\xe7\xe3o de vagas ou a classifica\xe7\xe3o.","O grupo vem do cadastro de Configura\xe7\xe3o, que s\xf3 aceita os quatro grupos do Anexo I da Resolu\xe7\xe3o\\nn\xba 805/2024/Consepe (Tecnol\xf3gica, Human\xedstica I, Human\xedstica II e Sa\xfade e Biol\xf3gicas) e p\xf5e o c\xf3digo e o\\nr\xf3tulo de cada um. Um curso que n\xe3o declara grupo n\xe3o gera esta recusa: a aus\xeancia \xe9 v\xe1lida.","Na distribui\xe7\xe3o de vagas a recusa vem no campo `distribuicaoVagas[<\xedndice>].grupoAreaEnem.codigo` ou `distribuicaoVagas[<\xedndice>].grupoAreaEnem.rotulo`, conforme o campo recusado, e\\nacumula, na mesma resposta, com as demais viola\xe7\xf5es da distribui\xe7\xe3o. Na classifica\xe7\xe3o vem no campo\\n`resolucaoPesoAreaEnem`, junto das demais viola\xe7\xf5es do quadro de pesos.","Este mesmo c\xf3digo tamb\xe9m aparece quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o publicada:\\nem toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios, as opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa\\nest\xe1 no cabe\xe7alho da p\xe1gina). Antes disso, o sistema confere a integridade dos bytes congelados:\\nbytes alterados depois do congelamento s\xe3o recusados por [`integridade_violada`](/erros/uniplus.selecao.envelope_codec.integridade_violada) e n\xe3o chegam a esta\\ncausa. Pelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz esse defeito, porque a\\ndefini\xe7\xe3o o recusa antes. Nessas leituras a resposta traz a lista `errors[]`, com o campo de cada recusa, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado.","Na releitura, o texto com n\xe3o-caractere (como U+FFFE) ou com surrogate sem par \xe9 recusado antes, como\\n[`envelope_malformado`](/erros/uniplus.selecao.envelope_codec.envelope_malformado), porque o sistema\\nreserializa os bytes pelo perfil can\xf4nico antes de ler cada campo; s\xf3 o texto com caractere nulo,\\nde controle ou de formata\xe7\xe3o chega a esta causa. O c\xf3digo ou o r\xf3tulo em branco, ou acima do limite, tamb\xe9m \xe9 recusado antes, pelo mesmo\\nmotivo.","O c\xf3digo e o r\xf3tulo s\xe3o conferidos juntos, e a recusa de um n\xe3o esconde a do outro. Em cada campo, a confer\xeancia vem\\ndepois da do campo em branco ([`codigo_obrigatorio`](/erros/uniplus.selecao.grupo_area_enem_snapshot.codigo_obrigatorio) e [`rotulo_obrigatorio`](/erros/uniplus.selecao.grupo_area_enem_snapshot.rotulo_obrigatorio)) e antes da do tamanho\\n([`tamanho_invalido`](/erros/uniplus.selecao.grupo_area_enem_snapshot.tamanho_invalido))."],"comoResolver":["Corrija o grupo de \xe1rea do ENEM no cadastro de Configura\xe7\xe3o (o do curso da oferta, ou o da linha de\\nPesos por \xc1rea da resolu\xe7\xe3o declarada), para um dos quatro grupos, e envie de novo a defini\xe7\xe3o da\\ndistribui\xe7\xe3o de vagas ou da classifica\xe7\xe3o. O c\xf3digo e o r\xf3tulo s\xe3o postos pelo cadastro: o\\ngrupo que chega sem eles, ou com texto fora do esperado, indica dado gravado por caminho que n\xe3o\\npassou por ele, e a causa \xe9 investigada pela equipe t\xe9cnica do Uni+.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no\\ncabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Simula\xe7\xe3o da distribui\xe7\xe3o de vagas do processo seletivo","Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Defini\xe7\xe3o de etapas e do cronograma das fases de processo publicado, quando declaram atos","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Grupo area enem snapshot"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);